vte[vte.length]=`<div id="text_83" class="textshirt mergershirt`+transws+`" style="width: 335px; white-space: normal; top: 46px; left: 407px; height: 360px;">he reached for his phone. For one second, he thought he would book the flight. Then he opened the camera. He took a photograph of the garden. He looked at it. It was not a very good photograph. The light was wrong. The hedge looked strange. The bird was only a small black dot. he laughed. Then he put the phone away.<br> The morning became afternoon. The afternoon became something softer. And he, who could have bought almost anything, finally understood something very simple. He did not need to buy the past. He did not need to repeat it. He did not need to improve the present by turning it into somewhere else. He only needed to be where he already was. So he was. And for once, that was enough.</div>`;
vte[vte.length]=`<div id="text_84" class="textshirt mergershirt`+transws+`" style="width: 335px; white-space: normal; top: 47px; left: 784px; height: 360px;"></div>`;

